def semver_sort(versions):
    def parse(v):
        core = v
        build = None
        if '+' in core:
            core, build = core.split('+', 1)
        pre = None
        if '-' in core:
            core, pre = core.split('-', 1)
        major, minor, patch = (int(x) for x in core.split('.'))
        pre_ids = pre.split('.') if pre is not None else None
        return (major, minor, patch, pre_ids)

    def key(v):
        major, minor, patch, pre_ids = parse(v)
        if pre_ids is None:
            pre_key = (1,)  # no prerelease sorts after
        else:
            ids_key = []
            for ident in pre_ids:
                if ident.isdigit():
                    ids_key.append((0, int(ident), ''))
                else:
                    ids_key.append((1, 0, ident))
            pre_key = (0, ids_key)
        return (major, minor, patch, pre_key)

    return sorted(versions, key=key)

